-- ONE-TIME clean-up for an integration DB that ran the old JSS trial migrations (prerelease only).
-- NOT a Flyway migration: run by hand with psql. Never run on production (it never had these migrations).
--
-- Order:
--   1. Stop the integration service
--   2. Back up the integration DB (pg_dump)
--   3. Run this script
--   4. Deploy the build containing V2_5_0__JSSBahmniFormMappings.sql and start the service
--
-- What it does:
--   - deletes the Bahmni mapping rows created by the 26 old JSS migrations (V2_4_5 .. V2_4_39),
--     matched by their Bahmni-side values, for the 'bahmni' integration system only
--   - removes those migrations from flyway_schema_history, so main's V2_4_5/6/8/9 (Wati) can apply
-- It keeps constants and mapping groups/types; V2_5_0 re-adds whatever mappings are still needed.

BEGIN;

-- Safety: the old and new mappings share Bahmni UUIDs, so running this AFTER V2_5_0 would delete the new mappings.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM flyway_schema_history WHERE script = 'V2_5_0__JSSBahmniFormMappings.sql') THEN
        RAISE EXCEPTION 'V2_5_0__JSSBahmniFormMappings.sql is already applied - this clean-up must run BEFORE it. Nothing was changed.';
    END IF;
END $$;

SELECT 'mapping rows to delete' AS what, COUNT(*)
FROM mapping_metadata
WHERE integration_system_id = (SELECT id FROM integration_system WHERE name = 'bahmni')
  AND int_system_value IN (
    '001a8cbb-b9bd-4060-a3c5-13c3754e93f3',
